#!/usr/bin/env node
// harness-gates (packed copy): runs the Harness gate engine inside this repository, with no Harness installed.
// Generated by `tools/gates/pack.mjs` in the Harness; do not edit (the integrity check fails on any change).
//
// Usage: node tools/harness-gates/cli.mjs [--config <file>] [--root <dir>] [--features a,b] [--json] [--versao]
//   --root    defaults to the repository root (two levels above this folder).
//   --config  defaults to <root>/harness-gates.json, else <root>/rastreio.config.json.
// Exit: 0 ok, 1 gate errors, 2 invalid config, 3 packed copy edited or incomplete.
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { verificaIntegridade } from './integridade.mjs';

const aqui = dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const opt = (n) => { const i = argv.indexOf(n); return i >= 0 ? argv[i + 1] : null; };

if (argv.includes('--versao')) {
  console.log(readFileSync(join(aqui, 'VERSION'), 'utf8').trim());
  process.exit(0);
}

const integ = verificaIntegridade(aqui);
if (!integ.ok) {
  console.error('[harness-gates] a cópia empacotada não confere com o lock:');
  for (const p of integ.problemas) console.error(`    ${p.tipo.padEnd(9)} ${p.arquivo}`);
  console.error('[harness-gates] não edite esta pasta; peça uma nova versão ao Harness (gates sync).');
  process.exit(3);
}

const root = resolve(opt('--root') || join(aqui, '..', '..'));
const config = opt('--config') ? resolve(opt('--config')) : [join(root, 'harness-gates.json'), join(root, 'rastreio.config.json')].find(existsSync);
if (!config) {
  console.error(`[harness-gates] config não encontrada em ${root} (esperado harness-gates.json ou rastreio.config.json; ou use --config).`);
  process.exit(2);
}
const args = [...argv];
if (!opt('--root')) args.push('--root', root);
if (!opt('--config')) args.push('--config', config);

const { roda } = await import(pathToFileURL(join(aqui, 'engine', 'rastreio', 'cli.mjs')).href);
process.exit(roda(args));
